    with tempfile.TemporaryDirectory() as scratch:
        proof_path = os.path.join(scratch, "proof.lrat")
        try:
            p = subprocess.run(
                ["cadical", "--no-binary", "--lrat=true", "-q",
                 "-t", str(limit), program, proof_path],
