                         sort_keys=True))
    elif "s UNSATISFIABLE" in out:
        print(json.dumps({"kind": "all", "bound": "inf", "cert": None},
                         sort_keys=True))
    else:
        return partial("z3 returned neither sat nor unsat",
                       returncode=p.returncode)


if __name__ == "__main__":
    main()

